import sys

sys.setrecursionlimit(200000)

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def maxPathSum(self, root: TreeNode) -> int:
        if root is None:
            return 0

        max_sum = float('-inf')

        def dfs(node):
            nonlocal max_sum
            if node is None:
                return float('-inf')

            left = dfs(node.left)
            right = dfs(node.right)

            if node.left is None and node.right is None:
                current_sum = node.val
                max_sum = max(max_sum, current_sum)
                return current_sum

            current_sum = node.val
            if left != float('-inf'):
                current_sum = max(current_sum, node.val + left)
            if right != float('-inf'):
                current_sum = max(current_sum, node.sum_val := node.val + right)

            max_sum = max(max_sum, current_sum)
            return current_sum

        dfs(root)
        return max_sum

def main():
    lines = sys.stdin.read().strip().split('\n')
    if not lines:
        return

    n = int(lines[0])
    if n == 0:
        print("0")
        return

    adj = [None] * (n + 1)
    parents = {}
    edges = []

    for i in range(1, n + 1):
        parts = lines[i].split()
        val = int(parts[0])
        left = int(parts[1]) if len(parts) > 1 else 0
        right = int(parts[2]) if len(parts) > 2 else 0

        adj[i] = TreeNode(val)
        if left != 0:
            adj[left] = TreeNode(adj[i].val) if adj[left] is None else adj[left]
            adj[i].left = adj[left]
            parents[left] = i
        if right != 0:
            adj[right] = TreeNode(adj[i].val) if adj[right] is None else adj[right]
            adj[i].right = adj[right]
            parents[right] = i

    root_id = 1
    while root_id in parents:
        root_id = parents[root_id]

    sol = Solution()
    result = sol.maxPathSum(adj[root_id])
    print(result)

if __name__ == "__main__":
    main()
